import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};
  root.userData.timelines = [];
  root.userData.disposables = [];

  const spec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: new Color(spec.colors?.ink ?? '#16161d'),
    paper: new Color(spec.colors?.paper ?? '#e8ecf2'),
    accent: new Color(spec.colors?.accent ?? '#ff2a38'),
    surface: new Color(spec.colors?.surface ?? '#0b0b10'),
  };

  // --- Backdrop: engineered vertical gradient, fills hub frame ---
  const bgGeo = new PlaneGeometry(7.2, 6.2);
  const bgUv = uv();
  const bgGrad = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(0.0, 1.0, bgUv.y)
  );
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = bgGrad;
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  root.add(bg);
  root.userData.disposables.push(bgGeo, bgMat);

  // --- Main textured card plane ---
  const aspect = 320 / 512;
  const cardW = 3.2;
  const cardH = cardW * aspect;

  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });
  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0;
  root.add(card);
  root.userData.disposables.push(cardGeo, cardMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      const texNode = texture(tex, uv());
      cardMat.colorNode = texNode;
      cardMat.needsUpdate = true;
      root.userData.disposables.push(tex);
    });
  }

  // Static composition: no animation timelines required.
  // (userData.timelines stays empty.)

  root.userData.cleanup = () => {
    root.userData.timelines.forEach((tl) => tl?.kill());
    root.userData.disposables.forEach((d) => {
      if (d instanceof ctx.THREE.Texture) d.dispose();
      else if (d instanceof ctx.THREE.BufferGeometry) d.dispose();
      else if (d.dispose) d.dispose();
    });
  };

  return root;
}
